<?php elseif($type==='catalog'): ?><section class="uwsb-section"><div class="uwsb-grid"><?php foreach($cards as $c): ?><a class="uwsb-card" href="<?php echo esc_url($c['url']); ?>"><div class="uwsb-thumb"><?php echo UWSB_Renderer::monogram($c['name']); ?></div><h2><?php echo esc_html($c['name']); ?></h2><?php if($c['facts']): ?><p><?php echo esc_html($c['facts'][0]); ?></p><?php endif; ?><?php if($c['price']): ?><strong><?php echo esc_html($c['price']); ?></strong><?php endif; ?></a><?php endforeach; ?></div></section>
<?php elseif($type==='product'): $it=$plan['item']??[]; ?><section class="uwsb-section uwsb-product"><div class="uwsb-facts"><h2><?php echo $project['lang']==='ru'?'Факты':'Факти'; ?></h2><?php if(!empty($it['facts'])):?><ul><?php foreach($it['facts'] as $f):?><li><?php echo esc_html($f); ?></li><?php endforeach;?></ul><?php else:?><p><?php echo $project['lang']==='ru'?'Дополнительные характеристики не указаны.':'Додаткові характеристики не вказані.';?></p><?php endif;?></div><?php if(!empty($it['price'])):?><div class="uwsb-price"><?php echo esc_html($it['price']); ?></div><?php endif;?></section>
