<?php elseif($type==='contacts'): ?><section class="uwsb-section"><h2><?php echo $project['lang']==='ru'?'Связаться':'Зв’язатися'; ?></h2><p><?php echo nl2br(esc_html($plan['contacts']??'')); ?></p></section><?php endif; ?>
